import{_ as o,o as a,c as t,a4 as i}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"工位 2 提示词 — shared/pkg：abstraction 全量补齐 + auth/repository 提升","description":"","frontmatter":{"title":"工位 2 提示词 — shared/pkg：abstraction 全量补齐 + auth/repository 提升","date":"2026-09-17T00:00:00.000Z"},"headers":[],"relativePath":"posts/工位2-sharedpkg提示词.md","filePath":"posts/工位2-sharedpkg提示词.md"}'),r={name:"posts/工位2-sharedpkg提示词.md"};function s(c,e,d,l,g,n){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="工位-2-提示词-—-shared-pkg-abstraction-全量补齐-auth-repository-提升" tabindex="-1">工位 2 提示词 — shared/pkg：abstraction 全量补齐 + auth/repository 提升 <a class="header-anchor" href="#工位-2-提示词-—-shared-pkg-abstraction-全量补齐-auth-repository-提升" aria-label="Permalink to &quot;工位 2 提示词 — shared/pkg：abstraction 全量补齐 + auth/repository 提升&quot;">​</a></h1><p>你在 /home/a1/mybilibili 仓库，负责提升 shared/pkg（module mybilibili/pkg，go 1.26.5）的测试覆盖率。 本工位重点是把 <code>abstraction</code> 包补齐到 85%+，并把 auth、repository 提到 85%+。</p><h2 id="目标任务" tabindex="-1">目标任务 <a class="header-anchor" href="#目标任务" aria-label="Permalink to &quot;目标任务&quot;">​</a></h2><h3 id="_1-abstraction-当前-63-0-→-目标-85" tabindex="-1">1. abstraction（当前 63.0%）→ 目标 85%+ <a class="header-anchor" href="#_1-abstraction-当前-63-0-→-目标-85" aria-label="Permalink to &quot;1. abstraction（当前 63.0%）→ 目标 85%+&quot;">​</a></h3><p>目录：<code>/home/a1/mybilibili/shared/pkg/abstraction/</code>。 已有测试：discovery_memory_test.go、factory_test.go、stubs_test.go、file_queue_test.go、ollama_caller_test.go。 <strong>未测的 11 个文件</strong>：</p><ul><li><code>minio_storage.go</code>（MinIO 存储网关）</li><li><code>nats_queue.go</code>（NATS 队列）</li><li><code>redis_cache.go</code>（Redis 缓存；<code>go test ./abstraction/... -cover</code> 会显示 redis 相关行未覆盖）</li><li><code>cache_store.go</code> / <code>document_store.go</code> / <code>message_queue.go</code>（接口 + 可能有内存/默认实现）</li><li><code>search_engine.go</code> / <code>service_caller.go</code> / <code>service_discovery.go</code>（抽象接口，可能有 grpc 实现）</li><li><code>pg_jsonb.go</code> / <code>storage_service.go</code></li></ul><p><strong>策略（按优先级）：</strong></p><ol><li><strong>优先测接口约定 + 内存实现</strong>：stubs.go 已提供 memory 实现，先测这些接口的契约行为。</li><li><strong>redis_cache</strong>：用 <code>github.com/alicebob/miniredis/v2</code>（若不在依赖里，在 go.mod 加直接依赖并 <code>go mod tidy</code>）或注入 fake 客户端。</li><li><strong>nats_queue</strong>：用 <code>github.com/nats-io/nats-server/v2</code> 内嵌 server 或 nats.go 的 ephemeral server。</li><li><strong>minio_storage</strong>：若用 minio-go 具体类型且难 mock，可测其接口层分支（nil 检查、错误路径）；确属无法注入的，跳过并报告，不改生产代码加接口。</li><li><strong>pg_jsonb / storage_service / search_engine / service_caller / service_discovery</strong>：读源码看是纯数据结构还是抽象声明；纯逻辑直接测，空接口可补契约性示例。</li></ol><p>先看 <code>notimpl.go</code>、<code>stubs.go</code> 了解约定，再逐个文件确认哪些可直接测。</p><h3 id="_2-auth-70-3-→-目标-85" tabindex="-1">2. auth（70.3%）→ 目标 85%+ <a class="header-anchor" href="#_2-auth-70-3-→-目标-85" aria-label="Permalink to &quot;2. auth（70.3%）→ 目标 85%+&quot;">​</a></h3><p>目录：<code>/home/a1/mybilibili/shared/pkg/auth/</code>，已有 jwt_test.go、middleware_test.go。 读 <code>jwt.go</code>、<code>middleware.go</code> 找未覆盖分支（无 token、过期 token、非法签名、错误 claim、header 缺失等），用 <code>go test -cover ./auth/</code> 定位。</p><h3 id="_3-repository-66-7-→-目标-85" tabindex="-1">3. repository（66.7%）→ 目标 85%+ <a class="header-anchor" href="#_3-repository-66-7-→-目标-85" aria-label="Permalink to &quot;3. repository（66.7%）→ 目标 85%+&quot;">​</a></h3><p>目录：<code>/home/a1/mybilibili/shared/pkg/repository/</code>，有 metrics.go、nullutil.go。 已有 nullutil_test.go。读 <code>metrics.go</code> 补未覆盖分支。</p><h2 id="技术要点" tabindex="-1">技术要点 <a class="header-anchor" href="#技术要点" aria-label="Permalink to &quot;技术要点&quot;">​</a></h2><ul><li>测试放同目录，命名 <code>xxx_test.go</code>；若依赖新库（miniredis、nats-server），先查 go.work.sum/go.mod，决定加直接依赖并跑 <code>cd /home/a1/mybilibili/shared/pkg &amp;&amp; go mod tidy</code>（只允许加依赖，不乱动 go.mod 其他内容）。</li><li><strong>绝不修改已有测试文件和生产代码</strong>；编译错误确认为 bug 才最小修并报告。</li><li>每完成一个文件/子包立即验证：<code>cd /home/a1/mybilibili/shared/pkg &amp;&amp; go test ./abstraction/...</code>（auth：<code>./auth/...</code>，repository：<code>./repository/...</code>）。</li><li>验收覆盖：<code>cd /home/a1/mybilibili/shared/pkg &amp;&amp; go test ./abstraction/... ./auth/... ./repository/... -cover | grep coverage</code></li><li>最终 <code>cd /home/a1/mybilibili/shared/pkg &amp;&amp; go test ./...</code> 与 <code>go vet ./...</code> 必须通过。</li><li>注意：<code>pb/</code>（生成代码）与 <code>models/</code> 不要求测试，勿在这两个包浪费时间。</li></ul><h2 id="报告内容" tabindex="-1">报告内容 <a class="header-anchor" href="#报告内容" aria-label="Permalink to &quot;报告内容&quot;">​</a></h2><ul><li>每个子包覆盖率 before/after</li><li>新建测试文件清单</li><li>新增的依赖（如有）</li><li>遇到的问题与处理</li><li>不要 git commit/push。</li></ul>',17)])])}const m=o(r,[["render",s]]);export{p as __pageData,m as default};
